/**
 * gpm-core / camera technique library
 *
 * PURE module. Ported from the Grok "Prompt Manager Pro" extension CAM_LIBRARY.
 * Movement cards carry a pre-rendered inline SVG diagram; every other category
 * carries a jpg thumbnail filename under frontend/assets/gpm-camera/.
 */

export type CameraCategory =
  | "Angles" | "Sizes" | "Framing" | "Movement" | "Lighting" | "Film Stocks" | "Movie Looks";

export interface CameraCard {
  id: string;
  cat: CameraCategory;
  label: string;
  phrase: string;
  /** jpg thumbnail filename under frontend/assets/gpm-camera/ (non-movement cards). */
  image?: string;
  /** Pre-rendered inline SVG diagram (movement cards). */
  svg?: string;
}

